#[state]
enum LightState {
    Off,
    On,
}

#[machine]
struct LightSwitch<LightState> {
    name: String,
}

let light = LightSwitch::<Off>::builder()
    .name("desk lamp".to_owned())
    .build();

let light = light.switch_on();
let _light = light.switch_off();

#[state]
enum TaskState {
    Draft,
    InReview(ReviewData),
    Published,
}

struct ReviewData {
    reviewer: String,
}

struct TaskRow {
    id: u64,
    status: &'static str,
    reviewer: Option<String>,
}

#[validators(Task)]
impl TaskRow {
    fn is_in_review(&self) -> statum::Result<String> {
        if self.status == "in_review" {
            self.reviewer.clone().ok_or(statum::Error::InvalidState)
        } else {
            Err(statum::Error::InvalidState)
        }
    }
}

